<script>
  import { createState } from 'svelte/store';

  let count = createState(0);

  function decrement() {
    count.update(c => c - 1);
  }

  function increment() {
    count.update(c => c + 1);
  }
</script>

<div class="counter">
  <button data-testid="decrement-button" on:click={decrement}>-</button>
  <span data-testid="count-value">{$count}</span>
  <button data-testid="increment-button" on:click={increment}>+</button>
</div>
