<script>
  import { $state, $effect } from 'svelte/store';

  let number = $state(5);
  $effect(() => number.update(val => val * 2));
  let doubled = $state();

  function increment() {
    number.update(val => val + 1);
  }
</script>

<div>
  <p data-testid="number-value">Number: {number}</p>
  <p data-testid="doubled-value">Doubled: {doubled}</p>
  <button data-testid="increment-button" on:click={increment}>Increment</button>
</div>
